package com.rulecraft.decisionops.expressions;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.*;
import com.rulecraft.decisionops.expressions.DecisionExpressionService.*;import com.rulecraft.decisionops.expressions.domain.ExpressionValidationStatus;
import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;
import com.rulecraft.decisionops.identity.domain.*;import com.rulecraft.decisionops.identity.persistence.UserAccountRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;
import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectService;import com.rulecraft.decisionops.projects.domain.ProjectRole;import com.rulecraft.decisionops.tables.DecisionTableService;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.crypto.password.PasswordEncoder;

@SpringBootTest
class DecisionExpressionIntegrationTest {
    @Autowired DecisionExpressionService expressions;@Autowired DecisionTableService tables;@Autowired DecisionGraphService graphs;@Autowired CatalogService catalog;@Autowired ProjectService projects;
    @Autowired UserAccountRepository users;@Autowired PasswordEncoder passwordEncoder;@Autowired Clock clock;@Autowired JdbcClient jdbc;RuleCraftPrincipal admin;
    @BeforeEach void actor(){admin=new RuleCraftPrincipal(users.findForLogin("acme-rules","admin@example.test").orElseThrow(),"acme-rules");}

    @Test void persistsAndRevalidatesTypedSafeExpression(){var fixture=fixture();var empty=expressions.initialize(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId());assertThat(empty.validationStatus()).isEqualTo(ExpressionValidationStatus.INVALID);
        var saved=expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(empty.version(),"if score >= 700 and lower(country) = \"us\" then true else false"));
        assertThat(saved.validationStatus()).isEqualTo(ExpressionValidationStatus.VALID);assertThat(saved.inferredType()).isEqualTo("BOOLEAN");assertThat(saved.issues()).isEmpty();
        assertThat(expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId())).get().extracting(ExpressionView::source).isEqualTo(saved.source());
        var graph=graphs.get(admin,fixture.projectId(),fixture.serviceId());var changed=graph.nodes().stream().map(node->{var base=command(node);if(!node.id().equals(fixture.nodeId()))return base;var ports=base.ports().stream().map(port->port.id().equals(fixture.scorePortId())?new PortCommand(port.id(),port.direction(),port.portKey(),port.label(),new DecisionGraphService.TypeRefCommand(BuiltinType.TEXT,null),port.required(),port.position()):port).toList();return new NodeCommand(base.id(),base.nodeKey(),base.name(),base.kind(),base.serviceFieldKey(),base.positionX(),base.positionY(),ports);}).toList();
        graphs.update(admin,fixture.projectId(),fixture.serviceId(),new GraphCommand(graph.version(),changed,List.of()));var drifted=expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId()).orElseThrow();assertThat(drifted.validationStatus()).isEqualTo(ExpressionValidationStatus.INVALID);assertThat(drifted.issues()).extracting("code").contains("RC-EXPR-OPERATOR-TYPE");
        assertThat(jdbc.sql("select count(*) from audit_event where action = 'DECISION_EXPRESSION_UPDATED'").query(Long.class).single()).isPositive();}

    @Test void savesSyntaxTypeAndUnsafeFunctionDiagnosticsAndRejectsStaleWrite(){var fixture=fixture();var value=expressions.initialize(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId());
        var syntax=expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(value.version(),"if score then"));assertThat(syntax.validationStatus()).isEqualTo(ExpressionValidationStatus.INVALID);assertThat(syntax.issues()).extracting("code").contains("RC-EXPR-SYNTAX");
        var unsafe=expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(syntax.version(),"system(score)"));assertThat(unsafe.issues()).extracting("code").contains("RC-EXPR-FUNCTION");
        var mismatch=expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(unsafe.version(),"score + 1"));assertThat(mismatch.issues()).extracting("code").contains("RC-EXPR-RESULT-TYPE");
        assertCode("RC-EXPR-STALE",()->expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(unsafe.version(),"true")));}

    @Test void resolvesObjectFieldsAndEnumLiterals(){var project=projects.create(admin,key("P"),"Object expressions",null);var risk=catalog.createType(admin,project.id(),new TypeCommand(key("RISK"),"Risk band",null,TypeKind.ENUM,null,List.of(),List.of(new EnumValueCommand("LOW","Low"),new EnumValueCommand("HIGH","High")),null));var applicant=catalog.createType(admin,project.id(),new TypeCommand(key("APP"),"Applicant",null,TypeKind.OBJECT,null,List.of(new FieldCommand("age","Age",builtin(BuiltinType.NUMBER),true),new FieldCommand("riskBand","Risk band",custom(risk.id()),true)),List.of(),null));
        var service=catalog.createService(admin,project.id(),new DecisionServiceCommand(key("SVC"),"Object eligibility",null,List.of(new FieldCommand("applicant","Applicant",custom(applicant.id()),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),null));var graph=graphs.initialize(admin,project.id(),service.id());var nodeId=UUID.randomUUID();var input=port(GraphPortDirection.INPUT,"applicant",new DecisionGraphService.TypeRefCommand(null,applicant.id()),0);var output=port(GraphPortDirection.OUTPUT,"approved",new DecisionGraphService.TypeRefCommand(BuiltinType.BOOLEAN,null),0);var nodes=new ArrayList<NodeCommand>();graph.nodes().forEach(node->nodes.add(command(node)));nodes.add(new NodeCommand(nodeId,"objectEligibility","Object eligibility",GraphNodeKind.DECISION,null,240,120,List.of(input,output)));graphs.update(admin,project.id(),service.id(),new GraphCommand(graph.version(),nodes,List.of()));
        var value=expressions.initialize(admin,project.id(),service.id(),nodeId);var saved=expressions.update(admin,project.id(),service.id(),nodeId,new ExpressionCommand(value.version(),"applicant.age >= 18 and applicant.riskBand = \"LOW\""));assertThat(saved.validationStatus()).isEqualTo(ExpressionValidationStatus.VALID);}

    @Test void enforcesOneImplementationSupportsSwitchingAndViewerReadOnlyAccess(){var fixture=fixture();var expression=expressions.initialize(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId());assertCode("RC-IMPLEMENTATION-EXISTS",()->tables.initialize(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId()));
        var now=Instant.now(clock);var account=users.save(new UserAccount(admin.tenantId(),"expr-viewer"+UUID.randomUUID()+"@example.test","Evan Expression Viewer",passwordEncoder.encode("CorrectHorseBattery78!"),TenantRole.MEMBER,now));projects.upsertMember(admin,fixture.projectId(),account.getId(),ProjectRole.VIEWER);var viewer=new RuleCraftPrincipal(account,"acme-rules");assertThat(expressions.find(viewer,fixture.projectId(),fixture.serviceId(),fixture.nodeId())).isPresent();assertCode("RC-PROJECT-EDIT-FORBIDDEN",()->expressions.update(viewer,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(expression.version(),"true")));
        expressions.remove(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),expression.version());assertThat(expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId())).isEmpty();assertThat(tables.initialize(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId())).isNotNull();var other=fixture();var table=tables.initialize(admin,other.projectId(),other.serviceId(),other.nodeId());assertCode("RC-IMPLEMENTATION-EXISTS",()->expressions.initialize(admin,other.projectId(),other.serviceId(),other.nodeId()));tables.remove(admin,other.projectId(),other.serviceId(),other.nodeId(),table.version());assertThat(tables.find(admin,other.projectId(),other.serviceId(),other.nodeId())).isEmpty();assertThat(expressions.initialize(admin,other.projectId(),other.serviceId(),other.nodeId())).isNotNull();assertThat(jdbc.sql("select count(*) from audit_event where action in ('DECISION_EXPRESSION_REMOVED','DECISION_TABLE_REMOVED')").query(Long.class).single()).isEqualTo(2);}

    private Fixture fixture(){var project=projects.create(admin,key("P"),"Expressions",null);var service=catalog.createService(admin,project.id(),new DecisionServiceCommand(key("SVC"),"Eligibility expression",null,List.of(new FieldCommand("score","Score",builtin(BuiltinType.NUMBER),true),new FieldCommand("country","Country",builtin(BuiltinType.TEXT),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),null));var graph=graphs.initialize(admin,project.id(),service.id());var nodeId=UUID.randomUUID();var score=port(GraphPortDirection.INPUT,"score",new DecisionGraphService.TypeRefCommand(BuiltinType.NUMBER,null),0);var country=port(GraphPortDirection.INPUT,"country",new DecisionGraphService.TypeRefCommand(BuiltinType.TEXT,null),1);var output=port(GraphPortDirection.OUTPUT,"approved",new DecisionGraphService.TypeRefCommand(BuiltinType.BOOLEAN,null),0);var nodes=new ArrayList<NodeCommand>();graph.nodes().forEach(node->nodes.add(command(node)));nodes.add(new NodeCommand(nodeId,"eligibilityExpression","Eligibility expression",GraphNodeKind.DECISION,null,240,120,List.of(score,country,output)));graphs.update(admin,project.id(),service.id(),new GraphCommand(graph.version(),nodes,List.of()));return new Fixture(project.id(),service.id(),nodeId,score.id());}
    private PortCommand port(GraphPortDirection direction,String key,DecisionGraphService.TypeRefCommand type,int position){return new PortCommand(UUID.randomUUID(),direction,key,key,type,true,position);}private NodeCommand command(GraphNodeView node){return new NodeCommand(node.id(),node.nodeKey(),node.name(),node.kind(),node.serviceFieldKey(),node.positionX(),node.positionY(),node.ports().stream().map(port->new PortCommand(port.id(),port.direction(),port.portKey(),port.label(),port.type(),port.required(),port.position())).toList());}
    private CatalogService.TypeRefCommand builtin(BuiltinType type){return new CatalogService.TypeRefCommand(type,null);}private CatalogService.TypeRefCommand custom(UUID id){return new CatalogService.TypeRefCommand(null,id);}private String key(String prefix){return prefix+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase();}private void assertCode(String code,Runnable action){assertThatThrownBy(action::run).isInstanceOf(DomainProblemException.class).extracting("code").isEqualTo(code);}private record Fixture(UUID projectId,UUID serviceId,UUID nodeId,UUID scorePortId){}
}
